SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱祁镇", "aliases": ["明英宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明英宗，宣德10年（1435年）正月，朱祁镇即皇帝位。", "biography": null, "status": "draft", "id": "368e5a42-621f-5c8c-88c7-f59b8bb8a5cf"}, {"name": "石亨", "aliases": ["都督石亨"], "era": "明", "birth_year": null, "death_year": null, "description": "石亨奉命统领京营兵。", "biography": null, "status": "draft", "id": "9892b251-a863-5d74-9c23-727ee42a25de"}, {"name": "石彪", "aliases": ["遊擊將軍石彪"], "era": "明", "birth_year": null, "death_year": null, "description": "石彪奉命巡视边防。", "biography": null, "status": "draft", "id": "b3dd53cf-1dfa-5406-ba6a-f6de1d1bab3d"}, {"name": "朱瞻墡", "aliases": ["襄憲王"], "era": "明", "birth_year": null, "death_year": null, "description": "朱瞻墡以襄王身份入朝。", "biography": null, "status": "draft", "id": "93659a1a-4726-5db7-990a-075517e9294a"}, {"name": "孛来", "aliases": ["孛來"], "era": "明", "birth_year": null, "death_year": null, "description": "孛来率部进攻宁夏。", "biography": null, "status": "draft", "id": "002b89e8-be8d-5e7f-9365-e517b45d0c6d"}, {"name": "李文（明代高阳伯）", "aliases": ["大同總兵官李文"], "era": "明", "birth_year": null, "death_year": null, "description": "李文（明代高阳伯）以大同总兵身份负责防御。", "biography": null, "status": "draft", "id": "14d1ac06-5448-5549-9d68-55797b45cb7d"}, {"name": "杨能", "aliases": ["宣府總兵官楊能"], "era": "明", "birth_year": null, "death_year": null, "description": "杨能以宣府总兵身份负责防御。", "biography": null, "status": "draft", "id": "c1146d9d-6c64-5c37-b6e3-f8d30cdc2a89"}, {"name": "朱永", "aliases": ["撫寧伯朱永"], "era": "明", "birth_year": null, "death_year": null, "description": "朱永奉命防守宣府边境。", "biography": null, "status": "draft", "id": "ae57a93c-662c-5661-bac1-1efb9b8c3a63"}]'::jsonb)
