INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明英宗在南郊祭祀天地", "description": "天顺四年正月丁亥，明英宗朱祁镇在南郊举行祭祀天地的大典。", "start_year": 1460, "end_year": 1460, "time_original": "天顺四年正月丁亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0538f439-e51a-5396-a56c-191469f7cc6f"}, {"title": "石亨被下狱，不久去世", "description": "天顺四年正月癸卯，明廷以石亨获罪，将他关进监狱。石亨不久去世。", "start_year": 1460, "end_year": 1460, "time_original": "天顺四年正月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "492f3059-c565-5b87-b274-3b20f9afe106"}, {"title": "本纪记梧州被当地起事武装攻陷", "description": "天顺四年二月壬子，《明史》本纪记被原文称为“僮”的当地武装攻陷梧州。", "start_year": 1460, "end_year": 1460, "time_original": "天顺四年二月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "29ebb671-9d00-56a9-8c2d-495d5067a8c9"}, {"title": "明廷处死石彪", "description": "天顺四年二月丁卯，明廷处死石彪。", "start_year": 1460, "end_year": 1460, "time_original": "天顺四年二月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "744a0667-26a4-5883-ac3b-848a5127d993"}, {"title": "明廷授予王一夔等人进士资格", "description": "天顺四年三月庚辰，朝廷授予王一夔等人不同等第的进士资格。", "start_year": 1460, "end_year": 1460, "time_original": "天顺四年三月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "83847570-0ec8-52d5-aaa9-b2127f76d40b"}, {"title": "明廷豁免南直隶灾区秋粮", "description": "天顺四年三月戊戌，朝廷免除南直隶受灾地区应缴的秋粮。", "start_year": 1460, "end_year": 1460, "time_original": "天顺四年三月戊戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a2dc36fe-0972-5d85-9228-400b49014295"}, {"title": "明廷分派宦官督办浙、滇、闽、川银课", "description": "天顺四年四月己酉，朝廷分别派遣宦官到浙江、云南、福建和四川督办银课。", "start_year": 1460, "end_year": 1460, "time_original": "天顺四年四月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "050b25a9-0138-50d1-aec3-15bd98536cf5"}, {"title": "襄王朱瞻墡入朝", "description": "天顺四年四月壬子，襄王朱瞻墡来到京师朝见明英宗。", "start_year": 1460, "end_year": 1460, "time_original": "天顺四年四月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4b846a7f-73f2-5887-b3f9-200d1dfdbba3"}, {"title": "明廷豁免京畿和浙江灾区秋粮", "description": "天顺四年五月壬午，朝廷免除京畿和浙江受灾地区应缴的秋粮。", "start_year": 1460, "end_year": 1460, "time_original": "天顺四年五月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8157cebe-6f75-5bd7-8404-fa68d1e97ba2"}, {"title": "明廷停止由宦官督办苏州、杭州织造", "description": "天顺四年五月己亥，朝廷取消由宦官在苏州和杭州督办织造的安排。", "start_year": 1460, "end_year": 1460, "time_original": "天顺四年五月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "688ca982-4fc4-5612-93cc-af0908a3d778"}, {"title": "明廷豁免湖广灾区税粮", "description": "天顺四年六月癸亥，朝廷免除湖广受灾地区应缴的税粮。", "start_year": 1460, "end_year": 1460, "time_original": "天顺四年六月癸亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c6f3393f-6019-54b9-a8d1-dcdb201f35a0"}, {"title": "本纪记天顺四年七月初一发生日食", "description": "天顺四年七月初一，《英宗后纪》记发生日食。", "start_year": 1460, "end_year": 1460, "time_original": "天顺四年七月乙亥朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e4de4149-caa9-5bad-8a92-fbde25f6b7e1"}, {"title": "淮河决口淹没田宅，明廷派使者赈济", "description": "天顺四年七月辛卯条记，当地从五月降雨持续到七月，淮河决口，淹没军民的田地和房屋，朝廷派使者前往赈济。", "start_year": 1460, "end_year": 1460, "time_original": "天顺四年七月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "52584fbd-e1b9-58e6-b42e-a425474e6277"}, {"title": "孛来分三路进攻，李文、杨能负责边防", "description": "天顺四年八月甲子，孛来分三路进攻。大同总兵官李文、宣府总兵官杨能负责迎敌。《李文传》另记李文按兵未战。", "start_year": 1460, "end_year": 1460, "time_original": "天顺四年八月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "29af76fd-02c6-5c45-a9d4-1a49c0fced22"}, {"title": "孛来进兵雁门，劫掠忻、代、朔州", "description": "天顺四年八月癸酉，孛来率部进入雁门一带，劫掠忻州、代州和朔州。", "start_year": 1460, "end_year": 1460, "time_original": "天顺四年八月癸酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cdd615a2-61f1-5fc9-af20-91699c72451f"}, {"title": "孛来所部围攻大同右卫", "description": "天顺四年九月庚辰，孛来所部围攻大同右卫。", "start_year": 1460, 